let houseViewMode = "share";
function renderHouseChart(){
  const el = document.getElementById("chart-houses");
  const cap = document.getElementById("chart-houses-caption");
  const impactBox = document.getElementById("houses-impact");
  el.innerHTML = "";
  const topics = DATA.macro_house.filter(d=>d.Topic_Macro !== "Other / unclassified");

  if(houseViewMode === "share"){
    const sorted = [...topics].sort((a,b)=>b["RS_share_%"]-a["RS_share_%"]);
    sorted.forEach(d=>{
      const row = document.createElement("div"); row.className="chart-row";
      const label = document.createElement("div"); label.className="clabel"; label.textContent=d.Topic_Macro;
      const track = document.createElement("div"); track.className="ctrack"; track.style.position="relative";
      const mid = document.createElement("div"); mid.style.cssText="position:absolute;left:50%;top:0;bottom:0;width:1px;background:var(--ink);opacity:.3;";
      const lsShare = d["LS_share_%"], rsShare = d["RS_share_%"];
      const bar = document.createElement("div");
      bar.style.position="absolute"; bar.style.top="2px"; bar.style.bottom="2px"; bar.style.borderRadius="2px";
      if(rsShare >= lsShare){ bar.style.left="50%"; bar.style.width=(rsShare-50)+"%"; bar.style.background="var(--purple)"; }
      else { bar.style.right="50%"; bar.style.width=(lsShare-50)+"%"; bar.style.background="var(--blue)"; }
      track.appendChild(mid); track.appendChild(bar);
      const val = document.createElement("div"); val.className="cval"; val.style.width="76px"; val.textContent = (rsShare>=lsShare? "RS "+rsShare.toFixed(0)+"%" : "LS "+lsShare.toFixed(0)+"%");
      track.addEventListener("mousemove", e=>{ showTooltip(e.clientX,e.clientY, `<div class="tt-title">${d.Topic_Macro}</div>Lok Sabha: ${lsShare.toFixed(1)}% (${d["Lok Sabha"]})<br>Rajya Sabha: ${rsShare.toFixed(1)}% (${d["Rajya Sabha"]})`); });
      track.addEventListener("mouseleave", hideTooltip);
      row.appendChild(label); row.appendChild(track); row.appendChild(val);
      el.appendChild(row);
    });
    cap.textContent = "Share view — bar length = distance from a 50/50 split between Houses. Sorted by Rajya Sabha lean.";
    const rsLeaning = sorted.filter(d=>d["RS_share_%"]>50).length;
    impactBox.innerHTML = `<span class="im-label">Impact</span><b>${rsLeaning} of ${sorted.length}</b> classified topics lean Rajya Sabha — and every one of them (Defence, Foreign Affairs, Environment, Infrastructure) is a topic with no single constituency to answer to.`;
  } else {
    const sorted = [...topics].sort((a,b)=>b.Combined-a.Combined);
    const max = Math.max(...sorted.map(d=>d.Combined));
    sorted.forEach(d=>{
      const row = document.createElement("div"); row.className="chart-row";
      const label = document.createElement("div"); label.className="clabel"; label.textContent=d.Topic_Macro;
      const track = document.createElement("div"); track.className="ctrack";
      const lsFill=document.createElement("div"); lsFill.style.cssText=`height:100%;width:${d["Lok Sabha"]/max*100}%;background:var(--blue);border-radius:2px 0 0 2px;float:left;`;
      const rsFill=document.createElement("div"); rsFill.style.cssText=`height:100%;width:${d["Rajya Sabha"]/max*100}%;background:var(--purple);border-radius:0 2px 2px 0;float:left;margin-left:2px;`;
      track.appendChild(lsFill); track.appendChild(rsFill);
      const val = document.createElement("div"); val.className="cval"; val.textContent=d.Combined;
      track.addEventListener("mousemove", e=>{ showTooltip(e.clientX,e.clientY, `<div class="tt-title">${d.Topic_Macro}</div>Lok Sabha: ${d["Lok Sabha"]}<br>Rajya Sabha: ${d["Rajya Sabha"]}`); });
      track.addEventListener("mouseleave", hideTooltip);
      row.appendChild(label); row.appendChild(track); row.appendChild(val);
      el.appendChild(row);
    });
    cap.textContent = "Volume view — raw question counts per topic, both Houses. Sorted by combined total.";
    impactBox.innerHTML = `<span class="im-label">Impact</span>Transport & connectivity alone drew <b>680</b> questions — more than Defence, Foreign Affairs, and Environment combined, twice over.`;
  }
}
function renderHouseToggle(){
  const el = document.getElementById("toggle-3-controls");
  const modes = [["share","By lean (share of topic)"],["volume","By raw volume"]];
  modes.forEach(([mode,label])=>{
    const btn = document.createElement("button");
    btn.textContent = label; btn.className="toggle-btn";
    btn.setAttribute("data-mode", mode);
    if(mode===houseViewMode) btn.setAttribute("data-active","true");
    btn.addEventListener("click", ()=>{
      houseViewMode = mode;
      el.querySelectorAll("button").forEach(b=>b.setAttribute("data-active", b.getAttribute("data-mode")===mode?"true":"false"));
      renderHouseChart();
    });
    el.appendChild(btn);
  });
}

