function renderStateMap(){
  const el = document.getElementById("state-map");
  if(!el) return;

  // merge Ladakh into the J&K polygon — this boundary file predates the 2019 split
  const counts = Object.assign({}, DATA.state_counts);
  const jk = (counts["Jammu and Kashmir"]||0) + (counts["Ladakh"]||0);
  delete counts["Jammu and Kashmir"]; delete counts["Ladakh"];
  if(jk) counts["Jammu & Kashmir and Ladakh"] = jk;

  const ranked = Object.entries(counts).sort((a,b)=>b[1]-a[1]);
  const rankOf = {}; ranked.forEach(([s],idx)=>{ rankOf[s]=idx+1; });
  const max = ranked.length ? ranked[0][1] : 1;

  const NS = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(NS,"svg");
  svg.setAttribute("viewBox", `0 0 ${INDIA_GEO.w} ${INDIA_GEO.h}`);
  svg.setAttribute("role","img");
  svg.setAttribute("aria-label","Map of India shaded by how many Parliamentary Questions named each state");
  svg.style.cssText = "width:100%;height:auto;display:block;max-height:560px;margin:0 auto;";

  // white → blue ramp; states with no mentions get the neutral wash
  function fillFor(n){
    if(!n) return "#FFFFFF";
    const t = Math.pow(n/max, 0.62);
    const r = Math.round(233 + (31  - 233)*t);
    const g = Math.round(238 + (68  - 238)*t);
    const b = Math.round(248 + (163 - 248)*t);
    return `rgb(${r},${g},${b})`;
  }

  Object.entries(INDIA_GEO.paths).forEach(([state,dAttr])=>{
    const n = counts[state] || 0;
    const p = document.createElementNS(NS,"path");
    p.setAttribute("d", dAttr);
    p.setAttribute("fill", fillFor(n));
    p.setAttribute("stroke", "#252525");
    p.setAttribute("stroke-width", "1.1");
    p.setAttribute("stroke-linejoin","round");
    p.setAttribute("tabindex","0");
    p.style.cursor = "pointer";
    p.style.transition = "fill .1s";

    const ex = (DATA.state_examples[state]||[]).slice(0,2).map(s=>"“"+s+"”").join("<br>");
    const rankStr = n ? `#${rankOf[state]} of ${ranked.length} by mentions` : "Not named in any question this session";
    const show = ev=>{
      p.setAttribute("stroke-width","2.4");
      showTooltip(ev.clientX, ev.clientY,
        `<div class="tt-title">${state} — ${n} question${n===1?"":"s"}</div>${rankStr}${ex?"<br>"+ex:""}`);
    };
    const hide = ()=>{ p.setAttribute("stroke-width","1.1"); hideTooltip(); };
    p.addEventListener("mousemove", show);
    p.addEventListener("mouseleave", hide);
    p.addEventListener("focus", ev=>{
      const r = p.getBoundingClientRect();
      p.setAttribute("stroke-width","2.4");
      showTooltip(r.left + r.width/2, r.top, `<div class="tt-title">${state} — ${n} question${n===1?"":"s"}</div>${rankStr}`);
    });
    p.addEventListener("blur", hide);
    svg.appendChild(p);
  });
  el.appendChild(svg);

  // legend
  const lg = document.createElement("div");
  lg.style.cssText = "display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:14px;padding-top:12px;border-top:1px solid var(--line);font-family:'IBM Plex Mono',monospace;font-size:11px;color:var(--muted);";
  const steps = [0, Math.round(max*0.15), Math.round(max*0.35), Math.round(max*0.6), max];
  let swatches = '<span>Questions naming the state</span><span style="flex:1"></span><span>0</span><span style="display:inline-flex;align-items:center;gap:2px">';
  steps.forEach(s=>{ swatches += `<i style="width:30px;height:12px;display:inline-block;background:${fillFor(s)};border:1px solid var(--line)"></i>`; });
  swatches += '</span><span>' + max + ' — ' + ranked[0][0] + '</span>';
  lg.innerHTML = swatches;
  el.appendChild(lg);
}

/* ============================================================
   ARTICLE 5 — neglect ranking, red alert on bottom two
   ============================================================ */
function renderNeglectChart(){
  const el = document.getElementById("chart-neglect");
  if(!el) return;
  const bottom = [...DATA.ministries_bottom10].reverse();
  const max = Math.max(...bottom.map(d=>d.combined));
  bottom.forEach(d=>{
    const row = document.createElement("div"); row.className="chart-row";
    const label = document.createElement("div"); label.className="clabel"; label.textContent=d.ministry;
    const track = document.createElement("div"); track.className="ctrack";
    const fill = document.createElement("div");
    fill.style.cssText = `height:100%;border-radius:2px;width:${Math.max(4,d.combined/max*100)}%;background:${d.combined<=10 ? "var(--red)" : "var(--ink)"};`;
    track.appendChild(fill);
    const val = document.createElement("div"); val.className="cval"; val.textContent=d.combined;
    track.addEventListener("mousemove", e=>{ showTooltip(e.clientX,e.clientY, `<div class="tt-title">${d.ministry}</div>Lok Sabha: ${d.ls}<br>Rajya Sabha: ${d.rs}<br>Combined: ${d.combined}`); });
    track.addEventListener("mouseleave", hideTooltip);
    row.appendChild(label); row.appendChild(track); row.appendChild(val);
    el.appendChild(row);
  });
}

