/* CYBER-CRIME CHART (board article) */
const CDATA = {
  states:{ cap:"Registered cases, 2024. Telangana and Karnataka together are nearly half the national total.", colour:"var(--purple)", suffix:"",
    rows:[["Telangana",27230],["Karnataka",21993],["Uttar Pradesh",11073],["Maharashtra",9922],["Bihar",6380],["Tamil Nadu",5793],["Kerala",2962],["Andhra Pradesh",2528]] },
  growth:{ cap:"Growth 2020 → 2024. The surge is in the south and east. Counter-trend: Assam fell ~88% and West Bengal ~60% — registration practice, not safety.", colour:"var(--red)", suffix:"%",
    rows:[["Tamil Nadu",641],["Kerala",595],["Telangana",442],["Bihar",322],["Haryana",177],["Karnataka",105]] },
  heads:{ cap:"By crime type, 2024. Fraud and cheating dominate — this is overwhelmingly a financial-loss story.", colour:"var(--blue)", suffix:"",
    rows:[["Computer-related",36920],["Fraud",29758],["Cheating",19296],["Obscene content",6990],["Other IPC/BNS",4109],["Stalking",1240]] }
};
function drawCyber(key){
  const d = CDATA[key];
  const wrap = document.getElementById("cyber-bars");
  if(!wrap) return;
  wrap.innerHTML = "";
  const max = Math.max(...d.rows.map(r=>r[1]));
  d.rows.forEach(([label,val])=>{
    const row = document.createElement("div"); row.className = "chart-row";
    const l = document.createElement("div"); l.className = "clabel"; l.textContent = label; l.title = label;
    const track = document.createElement("div"); track.className = "ctrack";
    const fill = document.createElement("div"); fill.className = "cfill";
    fill.style.width = (val/max*100)+"%"; fill.style.background = d.colour;
    track.appendChild(fill);
    const v = document.createElement("div"); v.className = "cval";
    v.textContent = val.toLocaleString("en-IN") + d.suffix;
    row.appendChild(l); row.appendChild(track); row.appendChild(v);
    wrap.appendChild(row);
  });
  const cap = document.getElementById("cyber-impact");
  if(cap) cap.innerHTML = '<span class="im-label">Reading this view</span>' + d.cap;
}
(function(){
  const t = document.getElementById("cyber-toggle");
  if(!t) return;
  t.addEventListener("click", e=>{
    const b = e.target.closest("button"); if(!b) return;
    t.querySelectorAll("button").forEach(x=>x.setAttribute("data-active","false"));
    b.setAttribute("data-active","true");
    drawCyber(b.getAttribute("data-set"));
  });
  drawCyber("states");
})();

/* SPEECH — per-article Listen control (Web Speech API, client-side only) */
(function(){
  const supported = "speechSynthesis" in window;
  document.querySelectorAll(".listen-btn").forEach(btn=>{
    if(!supported){ btn.querySelector(".lbl-text").textContent = "Voice unavailable"; btn.disabled = true; btn.style.opacity=0.5; return; }
    btn.addEventListener("click", ()=>{
      const targetId = btn.getAttribute("data-article");
      const isPlaying = btn.getAttribute("data-playing")==="true";
      window.speechSynthesis.cancel();
      document.querySelectorAll(".listen-btn").forEach(b=>{ b.setAttribute("data-playing","false"); b.querySelector(".lbl-text").textContent = "Listen to this article"; });
      if(isPlaying) return;
      const art = document.getElementById(targetId);
      const heading = art.querySelector("h1").innerText;
      const paras = Array.from(art.querySelectorAll(".supporting-copy, .pullquote")).map(p=>p.innerText).join(". ");
      const utter = new SpeechSynthesisUtterance(heading + ". " + paras);
      utter.rate = 1.0; utter.pitch = 1.0;
      utter.onend = ()=>{ btn.setAttribute("data-playing","false"); btn.querySelector(".lbl-text").textContent = "Listen to this article"; };
      utter.onerror = utter.onend;
      window.speechSynthesis.speak(utter);
      btn.setAttribute("data-playing","true");
      btn.querySelector(".lbl-text").textContent = "Stop listening";
    });
  });
})();

